insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, tiempo_constitucion, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, codigo_marca, anio_registro, cota_msnm, este, norte, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalecimiento_tecnico, fortalecimiento_academico, fortalecimiento_financiero, internacionalizacion, certificaciones, posicionamiento_marca, beneficios_ventanilla, fortalezas_ambiental, fortalezas_social, fortalezas_economico, debilidades_ambiental, debilidades_social, debilidades_financiera, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('83ea45e2-228f-4f97-83fa-f7c31583579d', 'ASOCIACIÓN CAMPESINA DE PRODUCTORES AGRICOLAS DE RIONEGRO SANTANDER -VEN FUTURO', generar_slug_unico('ASOCIACIÓN CAMPESINA DE PRODUCTORES AGRICOLAS DE RIONEGRO SANTANDER -VEN FUTURO', '83ea45e2-228f-4f97-83fa-f7c31583579d'), (select id from categorias_oficiales where slug = 'bioproductos-servicios-sostenibles'), 'Rionegro', (select id from veredas where municipio = 'Rionegro' and slug = 'la-union-de-galapagos-de-rionegro'), 'VEREDA LA UNION DE GALAPAGOS DE RIONEGRO', 7.400555555555556, -73.22277777777778, 'Transformación de cacao en chocolate de mesa, nits, trufas y mucilago comercializado con la marca chocolaterra', 'Transformación de cacao en chocolate de mesa, nits, trufas y mucilago comercializado con la marca chocolaterra', 'CHOCOLATE DE MESA', '3213441964', '573213441964', 'asociacionvenfuturo@gmail.com', 'ANA KATHERINE HERNANDEZ ANGARITA', '901478168-9', 'Jurídica', null, '44 MESES', 'Camara de comercio', 'ANA RUEDA', 'ACTIVO', 'Dinamizadoras', null, 2023, '982.5 msnm', '73°13''22"', '7°24''2"', 'ACTUALIZO', 'Se realizo visita y se actualizo ficha de verificacion', null, 'NO', 'ACUEDUCTO VEREDAL', null, 'NO', null, 'NO', 'NO', 'NO', null, null, null, 'SI', '2034-05-30', null, 'NO', null, null, null, null, 'NO', 'B2C', 'NO', null, 'Se requiere formación en mejorar las técnicas de transformación e investigación para obtener productos diferenciales', 'Cursos con SENA, Higiene y manipulación de alimentos. Chocolatería Fina Artesanal. Costos y presupuesto, Modelo Canvas, Iniciación cultivo de Cacao', 'Se requiere formación en educación financiera', 'Se requiere conocer y  capacitar en temas de exportación', 'Certificado de negocios verdes diciembre 6 de 2024', 'Redes sociales, Página web', null, 'Restauración y conservación de bosques. Producción agropecuaria sostenible (Amigable con el medio ambiente). Biodiversidad. Taller en BPA', 'Participación comunitaria en actividades. Proyectos de responsabilidad social. Formaciones complementarias con la comunidad, institución.', 'Modelo de negocio en crecimiento. econocimiento, Local, regional y nacional. Recursos tangibles importantes (Aval de confianza negocios verdes, Notificación sanitaria). Empresa legalmente registrada en Cámara de Comercio y RNT.', 'Falta de permisos de vertimiento. No se cuenta con plan formal de manejo ambiental. Espacios locativos para manejo de residuos sólidos. Infraestructura para biopreparados.', 'Falta de conectividad digital en la zona. Poca participación de otros actores del ente territorial. Deficiencia en material didáctico, (recursos tangibles) para formaciones. Falta de protocolos de atención al visitante y manejo de emergencias. (Botiquín PA, Camilla, Extintor).', 'Falta de equipos avanzados para mejorar producción. Falta de registro de la marca. Falta de equipos inmobiliarios en la oficina. No se cuenta con las tablas nutricionales de los productos', false, false, true, false, true);
